src = r'''#!/usr/bin/env python3
"""Find rational roots of roots(EXPR, x) lines in a Markdown file (exact arithmetic)."""
import json
import re
import sys
from fractions import Fraction
from math import gcd

MAXDEG = 8


class ParseError(Exception):
    pass


# Polynomials: list of Fraction, lowest degree first, no trailing zeros ([] = 0).
def trim(p):
    p = list(p)
    while p and p[-1] == 0:
        p.pop()
    return p


def padd(a, b):
    n = max(len(a), len(b))
    return trim([(a[i] if i < len(a) else 0) + (b[i] if i < len(b) else 0) for i in range(n)])


def pneg(a):
    return [-c for c in a]


def pmul(a, b):
    if not a or not b:
        return []
    r = [Fraction(0)] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        if x:
            for j, y in enumerate(b):
                r[i + j] += x * y
    if len(r) - 1 > 64:
        raise ParseError("degree too large")
    return trim(r)


TOKEN_RE = re.compile(r"\s*(?:(\d+)|(\*\*)|([+\-*/()])|(x)(?![A-Za-z0-9_]))")


def tokenize(s):
    toks, pos = [], 0
    s = s.rstrip()
    while pos < len(s):
        m = TOKEN_RE.match(s, pos)
        if not m or m.end() == pos:
            raise ParseError("bad token at %d" % pos)
        if m.group(1) is not None:
            toks.append(("num", int(m.group(1))))
        elif m.group(2):
            toks.append(("op", "**"))
        elif m.group(3):
            toks.append(("op", m.group(3)))
        else:
            toks.append(("x", None))
        pos = m.end()
        while pos < len(s) and s[pos].isspace():
            pos += 1
    return toks


class Parser:
    def __init__(self, toks):
        self.t, self.i = toks, 0

    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else (None, None)

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def parse(self):
        p = self.expr()
        if self.i != len(self.t):
            raise ParseError("trailing tokens")
        return p

    def expr(self):
        p = self.term()
        while self.peek() in (("op", "+"), ("op", "-")):
            op = self.take()[1]
            q = self.term()
            p = padd(p, q if op == "+" else pneg(q))
        return p

    def term(self):
        p = self.unary()
        while self.peek() in (("op", "*"), ("op", "/")):
            op = self.take()[1]
            q = self.unary()
            if op == "*":
                p = pmul(p, q)
            else:
                if len(q) != 1:
                    raise ParseError("division by non-constant or zero")
                p = [c / q[0] for c in p]
        return p

    def unary(self):
        if self.peek() == ("op", "-"):
            self.take()
            return pneg(self.unary())
        if self.peek() == ("op", "+"):
            self.take()
            return self.unary()
        return self.power()

    def power(self):
        base = self.atom()
        if self.peek() == ("op", "**"):
            self.take()
            kind, val = self.take()
            if kind != "num" or val > MAXDEG:
                raise ParseError("exponent must be a literal integer 0..8")
            r = [Fraction(1)]
            for _ in range(val):
                r = pmul(r, base)
            return r
        return base

    def atom(self):
        kind, val = self.take()
        if kind == "num":
            return trim([Fraction(val)])
        if kind == "x":
            return [Fraction(0), Fraction(1)]
        if (kind, val) == ("op", "("):
            p = self.expr()
            if self.take() != ("op", ")"):
                raise ParseError("missing )")
            return p
        raise ParseError("unexpected token")


def extract_expr(line):
    """Return EXPR text from 'roots(EXPR, x)  # comment', or None."""
    s = line.strip()
    if not s.startswith("roots("):
        return None
    depth, start, comma, end = 0, len("roots("), None, None
    for k in range(start, len(s)):
        ch = s[k]
        if ch == "(":
            depth += 1
        elif ch == ")":
            if depth == 0:
                end = k
                break
            depth -= 1
        elif ch == "," and depth == 0:
            if comma is not None:
                raise ParseError("too many arguments")
            comma = k
    if end is None or comma is None:
        raise ParseError("malformed roots call")
    if s[comma + 1:end].strip() != "x":
        raise ParseError("variable must be x")
    rest = s[end + 1:].strip()
    if rest and not rest.startswith("#"):
        raise ParseError("trailing text")
    return s[start:comma]


def divisors(n):
    n = abs(n)
    small, large = [], []
    d = 1
    while d * d <= n:
        if n % d == 0:
            small.append(d)
            if d * d != n:
                large.append(n // d)
        d += 1
    return small + large[::-1]


def synth_div(p_high, r):
    """Divide highest-first poly by (x - r); return (quotient, remainder)."""
    q, acc = [], Fraction(0)
    for c in p_high:
        acc = acc * r + c
        q.append(acc)
    return q[:-1], q[-1]


def fmt(f):
    f = Fraction(f)
    return str(f.numerator) if f.denominator == 1 else "%d/%d" % (f.numerator, f.denominator)


def analyze(poly_low):
    high = poly_low[::-1]
    coefficients = [fmt(c) for c in high]
    roots = {}
    work = list(high)
    # zero roots
    while len(work) > 1 and work[-1] == 0:
        work.pop()
        roots[Fraction(0)] = roots.get(Fraction(0), 0) + 1
    if len(work) > 1:
        # primitive integer version for rational root theorem
        den = 1
        for c in work:
            den = den * c.denominator // gcd(den, c.denominator)
        ints = [int(c * den) for c in work]
        g = 0
        for c in ints:
            g = gcd(g, c)
        ints = [c // g for c in ints]
        cands = set()
        for p in divisors(ints[-1]):
            for q in divisors(ints[0]):
                cands.add(Fraction(p, q))
                cands.add(Fraction(-p, q))
        for r in sorted(cands):
            while len(work) > 1:
                q, rem = synth_div(work, r)
                if rem != 0:
                    break
                work = q
                roots[r] = roots.get(r, 0) + 1
    return {
        "coefficients": coefficients,
        "rational_roots": [{"root": fmt(r), "multiplicity": m} for r, m in sorted(roots.items())],
        "residual_coefficients": [fmt(c) for c in work],
    }


def main(argv):
    if len(argv) != 2:
        sys.stdout.write(json.dumps({"error": "usage: roots.py INPUT.md"}) + "\n")
        return 2
    with open(argv[1], "r", encoding="utf-8") as fh:
        text = fh.read()
    cases = []
    for line in text.splitlines():
        try:
            e = extract_expr(line)
            if e is None:
                continue
            poly = Parser(tokenize(e)).parse()
        except (ParseError, RecursionError, ZeroDivisionError):
            continue  # out-of-scope line; not a valid example
        if not poly:
            continue  # zero polynomial is out of scope
        cases.append(analyze(poly))
    sys.stdout.write(json.dumps({"cases": cases}) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
'''
